            case "handling_time" -> "AVG(TIMESTAMPDIFF(HOUR, jp.created_at, ra.created_at))";
            case "takedown_count" -> "SUM(CASE WHEN ra.action = 'TAKEDOWN' THEN 1 ELSE 0 END)";
