        }
        if (dimension.equals("location_state")) {
            sql.append("JOIN locations loc ON loc.id = jp.location_id ");
        }
        if (dimension.equals("reviewer") && table.equals("review_actions")) {
            sql.append("JOIN users usr ON usr.id = ra.reviewer_id ");
        }
