            sql.append("AND jp.status IN (" + statusList + ") ");
        }
        sql.append("GROUP BY dimension ORDER BY dimension");

        Query query = entityManager.createNativeQuery(sql);
        query.setParameter("from", from);
        query.setParameter("to", to);
        List<Object[]> raw = query.getResultList();
        List<Map<String, Object>> rows = new ArrayList<>();
        for (Object[] row : raw) {
            Map<String, Object> map = new HashMap<>();
            map.put("dimension", row[0]);
            map.put("value", row[1]);
            rows.add(map);
        }
        return rows;
    }

    private String resolveDimension(String dimension, String table) {
        return switch (dimension) {
            case "date_daily" -> "DATE(created_at)";
            case "date_weekly" -> "DATE_FORMAT(created_at, '%x-%v')";
            case "date_monthly" -> "DATE_FORMAT(created_at, '%Y-%m')";
            case "status" -> "job_postings.status";
            case "category" -> "categories.name";
            case "location_state" -> "locations.state";
            case "reviewer" -> "users.username";
            default -> "DATE(created_at)";
        };
    }

    byte[] toCsv(List<Map<String, Object>> rows) {
