        JobPosting job = buildJob(JobStatus.DRAFT);
        when(jobPostingRepository.findByIdAndEmployer_Id(job.getId(), authUser.id())).thenReturn(Optional.of(job));
        jobPostingService.submitForReview(job.getId(), authUser);
